<?php

declare(strict_types=1);

namespace AC\Service;

use AC\Capabilities;
use AC\Registerable;
use WP_Query;

/**
 * Filters the post list table for links generated by the Related Posts column.
 * WordPress ignores the meta_value query vars on the post list screen, so the
 * column links carry dedicated query vars that are mapped to a meta query here.
 */
final class RelatedPostsFilter implements Registerable
{
    public function register(): void
    {
        add_action('pre_get_posts', [$this, 'handle']);
    }

    public function handle(WP_Query $query): void
    {
        if (! $query->is_admin || ! $query->is_main_query()) {
            return;
        }

        $related_id = absint($_GET['ac_related'] ?? 0);
        $meta_key = isset($_GET['ac_meta_key'])
            ? sanitize_text_field(wp_unslash($_GET['ac_meta_key']))
            : '';

        if (! $related_id || ! $meta_key || ! current_user_can(Capabilities::MANAGE)) {
            return;
        }

        $meta_query = $query->get('meta_query');
        $meta_query = is_array($meta_query) ? $meta_query : [];

        $meta_query[] = [
            'key'   => $meta_key,
            'value' => $related_id,
        ];

        $query->set('meta_query', $meta_query);
    }

}
